#!/usr/bin/env python3
"""Text selection utility, implemented from its command-line behavior."""
import os
import re
import sys
import unicodedata
from dataclasses import dataclass
from pathlib import Path

HELP_TEXT = None
WELCOME_TEXT = None


class Failure(Exception):
    pass


class ParseFailure(Exception):
    pass


class BoundsFailure(Exception):
    pass


class Panic(Exception):
    def __init__(self, location, message):
        self.location = location
        self.message = message


def utf8(s):
    return s.encode('utf-8', 'surrogateescape')


def runtime(message):
    raise Failure('tuc: runtime error. ' + message)


def panic_bounds():
    raise Panic('src/bounds/userboundslist.rs:50:14',
                'UserBoundsList must contain at least one UserBounds')


def panic_count(line):
    raise Panic('/workspace/src/cut_str.rs:%d' % line,
                "We didn't use an extract function that counted the number of fields")


@dataclass
class Bound:
    left: object
    right: object
    is_range: bool = False
    fallback: object = None

    def label(self):
        if not self.is_range:
            return str(self.left)
        return '%s:%s' % (self.left if self.left is not None else 1,
                          self.right if self.right is not None else '')


def number(s):
    if not re.fullmatch(r'[+-]?[0-9]+', s):
        raise ParseFailure('Not a number `%s`' % s)
    try:
        n = int(s)
    except ValueError:
        raise ParseFailure('Not a number `%s`' % s)
    if not -(1 << 63) <= n < (1 << 63):
        raise ParseFailure('Not a number `%s`' % s)
    if n == 0:
        raise ParseFailure('Zero is not a valid field')
    return n


def parse_sequence(s):
    result = []
    for item in s.split(','):
        if not item:
            raise ParseFailure('Field format error: empty field')
        bare, eq, fallback = item.partition('=')
        fallback = utf8(fallback) if eq else None
        if ':' in bare:
            a, b = bare.split(':', 1)
            if not a and not b:
                raise ParseFailure('Field format error, no numbers next to `:`')
            left = number(a) if a else None
            right = number(b) if b else None
            if left is not None and right is not None and (left > 0) == (right > 0) and left > right:
                raise ParseFailure('Field left value cannot be greater than right value')
            result.append(Bound(left, right, True, fallback))
        else:
            n = number(bare)
            result.append(Bound(n, n, False, fallback))
    return result


def parse_bounds(s):
    if not s:
        raise ParseFailure('UserBoundsList must contain at least one UserBounds')
    if '{' not in s and '}' not in s:
        return parse_sequence(s)
    result = []
    text = []
    i = 0
    while i < len(s):
        c = s[i]
        if c in '{}' and i + 1 < len(s) and s[i + 1] == c:
            text.append(c)
            i += 2
        elif c == '}':
            raise ParseFailure('Field format error: missing opening parenthesis')
        elif c == '{':
            if text:
                result.append(utf8(''.join(text)))
                text = []
            j = i + 1
            while j < len(s):
                if s[j] in '{}' and j + 1 < len(s) and s[j + 1] == s[j]:
                    j += 2
                elif s[j] == '}':
                    break
                else:
                    j += 1
            if j == len(s):
                raise ParseFailure('Field format error: missing closing parenthesis')
            result.extend(parse_sequence(s[i + 1:j]))
            i = j + 1
        else:
            text.append(c)
            i += 1
    if text:
        result.append(utf8(''.join(text)))
    if not any(isinstance(x, Bound) for x in result):
        panic_bounds()
    return result


class Arguments:
    """Consume independent options in the order exposed by the CLI."""
    def __init__(self, args):
        self.args = args[:]

    def flag(self, short, long):
        for i, a in enumerate(self.args):
            if a == long or (short and a == short):
                del self.args[i]
                return True
            if short and a.startswith('-') and not a.startswith('--') and len(a) > 2 and short[1] in a[1:]:
                j = a.index(short[1], 1)
                a = a[:j] + a[j + 1:]
                if a == '-':
                    del self.args[i]
                else:
                    self.args[i] = a
                return True
        return False

    def value(self, short, long, parser=lambda v: v, raw=False):
        for i, a in enumerate(self.args):
            key = None
            attached = None
            if a == short or a == long:
                key = a
            elif a.startswith(long + '='):
                key = long
                attached = a[len(long) + 1:]
            elif short and a.startswith(short) and len(a) > len(short):
                key = short
                attached = a[len(short):]
                if attached.startswith('='):
                    attached = attached[1:]
            if key is None:
                continue
            if attached is not None:
                if not attached and not raw:
                    raise Failure("the '%s' option doesn't have an associated value" % key)
                val = attached
                del self.args[i]
            else:
                if i + 1 == len(self.args):
                    if raw:
                        return None
                    raise Failure("the '%s' option doesn't have an associated value" % key)
                val = self.args[i + 1]
                del self.args[i:i + 2]
            try:
                return parser(val)
            except ParseFailure as e:
                raise Failure("failed to parse '%s': %s" % (val, e))
        return None


def parse_memory(s):
    if not s:
        raise ParseFailure('cannot parse integer from empty string')
    if not re.fullmatch(r'\+?[0-9]+', s):
        raise ParseFailure('invalid digit found in string')
    try:
        n = int(s)
    except ValueError:
        raise ParseFailure('number too large to fit in target type')
    if n > (1 << 64) - 1:
        raise ParseFailure('number too large to fit in target type')
    return n


def parse_trim(s):
    if s not in ('l', 'L', 'r', 'R', 'b', 'B'):
        raise ParseFailure('Valid trim values are (l|L)eft, (r|R)ight, (b|B)oth')
    return s.lower()


def rust_string(s):
    out = ['"']
    for c in s:
        out.append({'"': '\\"', '\\': '\\\\', '\n': '\\n', '\r': '\\r', '\t': '\\t', '\0': '\\0'}.get(c,
                   c if c.isprintable() else '\\u{%x}' % ord(c)))
    out.append('"')
    return ''.join(out)


def bounds_forward(parts, stream=False):
    last = 0
    for b in parts:
        if isinstance(b, bytes):
            continue
        a = 1 if b.left is None else b.left
        z = float('inf') if b.right is None else b.right
        if a < 1 or z < 1 or a < last or (stream and not b.is_range and a == last):
            return False
        last = z
    return True


def options(argv):
    a = Arguments(argv)
    if not argv:
        return 'welcome'
    if a.flag('-h', '--help'):
        return 'help'
    if a.flag('-V', '--version'):
        return 'version'
    f = a.value('-f', '--fields', parse_bounds)
    c = a.value('-c', '--characters', parse_bounds)
    b = a.value('-b', '--bytes', parse_bounds)
    l = a.value('-l', '--lines', parse_bounds)
    memory = a.value('-M', '--fixed-memory', parse_memory)
    delimiter = a.value('-d', '--delimiter', utf8)
    replacement = a.value('-r', '--replace-delimiter', utf8)
    regex = a.value('-e', '--regex')
    trim = a.value('-t', '--trim', parse_trim)
    greedy = a.flag('-g', '--greedy-delimiter')
    compress = a.flag('-p', '--compress-delimiter')
    only = a.flag('-s', '--only-delimited')
    zero = a.flag('-z', '--zero-terminated')
    complement = a.flag('-m', '--complement')
    join = a.flag('-j', '--join')
    nojoin = a.flag(None, '--no-join')
    js = a.flag(None, '--json')
    nommap = a.flag(None, '--no-mmap')
    fallback = a.value(None, '--fallback-oob', utf8, raw=True)
    path = None
    if len(a.args) == 1 and not a.args[0].startswith('-'):
        path = a.args.pop()
    if a.args:
        raise Failure('tuc: unexpected arguments: [%s]\nTry \'tuc --help\' for more information.' %
                      ', '.join(rust_string(s) for s in a.args))
    mode = 'fields' if f is not None else 'bytes' if b is not None else 'characters' if c is not None else 'lines' if l is not None else 'fields'
    parts = next((x for x in (f, c, b, l) if x is not None), [Bound(1, None, True)])
    sep = b'\0' if zero else b'\n'
    delimiter = (b'\t' if delimiter is None else delimiter) if mode == 'fields' else sep if mode == 'lines' else b''
    if join and nojoin:
        runtime("It's not possible to use --join and --no-join simultaneously")
    if replacement is not None and nojoin:
        runtime("You can't pass --no-join when using --replace, which implies --join")
    if js and nojoin:
        runtime('Using both --json and --no-join is not permitted')
    if js and replacement is not None:
        runtime('The use of --replace with --json is not supported')
    if js and mode not in ('fields', 'characters'):
        runtime('--json support is available only for --fields and --characters')
    if js and any(isinstance(x, bytes) for x in parts):
        runtime('Cannot format fields when using --json')
    if compress and mode not in ('fields', 'lines'):
        runtime('Delimiters can be compressed only with --fields and --lines')
    join = join or replacement is not None or js or (mode == 'lines' and not nojoin)
    if regex is not None and join and replacement is None and not js:
        runtime('Cannot use --regex and --join without --replace-delimiter')
    if regex is not None and compress and replacement is None:
        runtime('Cannot use --regex and --compress-delimiter without --replace-delimiter')
    if memory is not None:
        if memory == 0:
