    compiled = Regex(regex) if regex is not None else None
    if path is not None:
        if not os.path.exists(path):
            runtime('The file %s does not exist' % rust_string(path))
        if not os.path.isfile(path):
            runtime('The path %s is not a file' % rust_string(path))
    return dict(mode=mode, parts=parts, memory=memory, delimiter=delimiter,
                replacement=replacement, regex=compiled, trim=trim, greedy=greedy,
                compress=compress, only=only, sep=sep, complement=complement,
                join=join, json=js, fallback=fallback, path=path, nommap=nommap)


def convert(b, n, strict=False, reverse_error=False):
    left = 1 if b.left is None else b.left
    right = n if b.right is None else b.right
    def index(v):
        return v if v > 0 else n + v + 1
    start = index(left)
    end = index(right)
    if not 1 <= start <= n:
        raise BoundsFailure('Out of bounds: %s' % left)
    if strict and not 1 <= end <= n:
        v = left if reverse_error and left < 0 and right > 0 else right
        raise BoundsFailure('Out of bounds: %s' % v)
    end = max(1, min(n, end))
    if start > end:
        raise BoundsFailure('Field left value cannot be greater than right value')
    return start - 1, end


def characters(data):
    """Split valid scalar values; preserve runs of undecodable input intact."""
    result = []
    invalid = bytearray()
    i = 0
    while i < len(data):
        c = data[i]
        length = 1 if c < 0x80 else 2 if 0xc2 <= c <= 0xdf else 3 if 0xe0 <= c <= 0xef else 4 if 0xf0 <= c <= 0xf4 else 0
