        valid = bool(length) and len(chunk) == length
        if valid:
            try:
                chunk.decode('utf-8')
            except UnicodeDecodeError:
                valid = False
        if not valid:
            invalid.append(c)
            i += 1
        else:
            if invalid:
                result.append(bytes(invalid))
                invalid.clear()
            result.append(chunk)
            i += length
    if invalid:
        result.append(bytes(invalid))
    return result


