    if not delimiter:
        return [(i, i) for i in range(len(data) + 1)]
    result = []
    i = 0
    while True:
        p = data.find(delimiter, i)
        if p < 0:
            break
        result.append((p, p + len(delimiter)))
        i = p + len(delimiter)
    return result


def split_spans(data, spans):
    result = []
    start = 0
    for a, z in spans:
        result.append((start, a))
        start = z
    result.append((start, len(data)))
    return result


def escape_json(data):
    escapes = {8: b'\\b', 9: b'\\t', 10: b'\\n', 12: b'\\f', 13: b'\\r', 34: b'\\"', 92: b'\\\\'}
    result = [b'"']
    for b in data:
        result.append(escapes.get(b, ('\\u%04x' % b).encode() if b < 32 else bytes([b])))
    result.append(b'"')
    return b''.join(result)


def records(data, separator, strip_cr=False):
    start = 0
