        new = []
        for b in parts:
            if isinstance(b, bytes):
                new.append(b)
                continue
            left = b.left if b.left is not None else 1
            right = b.right if b.right is not None else count
            left = left if left > 0 else count + left + 1
            right = right if right > 0 else count + right + 1
            if not 1 <= left <= count or not 1 <= right <= count:
                panic_count(19746)
