# Regular expressions are translated to the standard engine. Matching works on
# Unicode when needed, while results and selection offsets remain byte-oriented.
class Regex:
    def __init__(self, pattern):
        self.pattern = pattern
        self.byte_mode = '(?-u' in pattern
        self.validate(pattern)
        translated = self.translate(pattern)
        self.translated = translated
        try:
            self.re = re.compile(utf8(translated) if self.byte_mode else translated)
        except (re.error, ValueError) as e:
            self.python_error(e, pattern)
        self.empty_re = None
        if not self.byte_mode:
            try:
                self.empty_re = re.compile(utf8(translated))
            except (re.error, ValueError):
                pass

    def error(self, start, end, message):
        pattern = self.pattern
        if '\n' in pattern:
            # The multiline layout is used by the expression parser's diagnostics.
            lines = pattern.split('\n')
            line = pattern[:start].count('\n')
            col = start - (pattern.rfind('\n', 0, start) + 1)
            shown = '\n'.join('%d: %s' % (i + 1, s) for i, s in enumerate(lines))
            annotation = ' ' * (col + len(str(line + 1)) + 2) + '^' * max(1, end - start)
            detail = shown + '\n' + annotation
        else:
            detail = '    ' + pattern + '\n    ' + ' ' * start + '^' * max(1, end - start)
        runtime('The regular expression is malformed. regex parse error:\n' + detail + '\nerror: ' + message)

    def validate(self, p):
        for token in ('(?=', '(?!', '(?<=', '(?<!'):
            i = p.find(token)
            if i >= 0:
                self.error(i, i + len(token), 'look-around, including look-ahead and look-behind, is not supported')
        for m in re.finditer(r'(?<!\\)\\([1-9])', p):
            self.error(m.start(), m.end(), 'backreferences are not supported')
        for m in re.finditer(r'\(\?([a-zA-Z-]+)(?:\)|:)', p):
            flags = m.group(1)
            for j, c in enumerate(flags):
                if c not in 'imsxUuR-':
                    self.error(m.start() + 2 + j, m.start() + 3 + j, 'unrecognized flag')
        for m in re.finditer(r'(?<!\\)\{([^}]*)\}?', p):
            if m.start() and p[m.start() - 1] in 'pPxu' and '\\' in p[max(0, m.start()-2):m.start()]:
                continue
            body = m.group(1)
            if not m.group(0).endswith('}'):
                self.error(m.start(), len(p), 'unclosed counted repetition')
            if not re.fullmatch(r'[0-9]+(?:,[0-9]*)?', body):
                self.error(m.start() + 1, m.start() + 2, 'repetition quantifier expects a valid decimal')
            if ',' in body:
                a, b = body.split(',')
                if b and int(a) > int(b):
                    self.error(m.start(), m.end(), 'invalid repetition count range, the start must be <= the end')

    def translate(self, p):
        p = p.replace('(?-u:', '(?:').replace('(?-u)', '')
        p = p.replace('(?u:', '(?:').replace('(?u)', '')
        p = p.replace('(?R)', '')
        ungreedy = '(?U)' in p
        p = p.replace('(?U)', '')
        if ungreedy:
            p = re.sub(r'(?<!\\)([+*?])(\?)?', lambda m: m.group(1) if m.group(2) else m.group(1) + '?', p)
        p = re.sub(r'\\[xu]\{([0-9a-fA-F]+)\}', lambda m: re.escape(chr(int(m.group(1), 16))), p)
        p = p.replace(r'\z', r'\Z')
        properties = {
            'L': r'[^\W\d_]', 'Letter': r'[^\W\d_]', 'Alphabetic': r'[^\W\d_]',
            'N': r'\d', 'Nd': r'\d', 'Number': r'\d', 'Decimal_Number': r'\d',
            'White_Space': r'\s', 'Whitespace': r'\s', 'Greek': r'[\u0370-\u03ff\u1f00-\u1fff]',
            'Latin': r'[A-Za-z\u00c0-\u024f\u1e00-\u1eff]',
            'Cyrillic': r'[\u0400-\u052f]', 'Han': r'[\u3400-\u9fff\U00020000-\U0003134f]',
            'ASCII': r'[\x00-\x7f]', 'Any': r'[\s\S]',
            'Lu': r'[A-ZÀ-ÖØ-Þ]', 'Ll': r'[a-zà-öø-ÿ]',
