            name = m.group(2) or m.group(3)
            if name not in properties:
                self.error(m.start(), m.end(), 'Unicode property not found')
            q = properties[name]
            if m.group(1) == 'P':
                if q.startswith('[^'):
                    q = '[' + q[2:]
                elif q.startswith('['):
