        classes = {'alnum':'A-Za-z0-9','alpha':'A-Za-z','ascii':r'\x00-\x7f',
                   'blank':r' \t','cntrl':r'\x00-\x1f\x7f','digit':'0-9',
                   'graph':r'\x21-\x7e','lower':'a-z','print':r'\x20-\x7e',
                   'punct':r'!-/:-@\[-`{-~','space':r' \t\r\n\v\f','upper':'A-Z',
                   'word':'A-Za-z0-9_','xdigit':'A-Fa-f0-9'}
