        return p

    def python_error(self, e, p):
        pos = getattr(e, 'pos', 0) or 0
        msg = str(e)
        if 'unterminated character set' in msg:
            self.error(pos, pos + 1, 'unclosed character class')
        if 'unterminated subpattern' in msg or 'missing )' in msg:
            self.error(pos, pos + 1, 'unclosed group')
        if 'unbalanced parenthesis' in msg:
            self.error(pos, pos + 1, 'unopened group')
        if 'nothing to repeat' in msg:
            self.error(pos, pos + 1, 'repetition operator missing expression')
        if 'bad escape' in msg:
            self.error(pos, pos + 2, 'unrecognized escape sequence')
        if 'bad character range' in msg:
            self.error(pos, pos + 3, 'invalid character class range, the start must be <= the end')
        self.error(pos, pos + 1, msg.split(' at position ')[0])

    def match_objects(self, data):
        if self.byte_mode:
            raw = [(m.start(), m.end(), m, None) for m in self.re.finditer(data)]
        else:
            text = data.decode('utf-8', 'surrogateescape')
