    def matches(self, data):
        return [(a, z) for a, z, _, _ in self.match_objects(data)]

    def expand(self, m, replacement):
        def ref(g):
            key = g.group(1)
            if key == b'$':
                return b'$'
            if key.startswith(b'{'):
                key = key[1:-1]
            key = key.decode('ascii', 'ignore')
            try:
                v = m.group(int(key) if key.isdigit() else key)
