            if v is None:
                return b''
            return utf8(v) if isinstance(v, str) else v
        return re.sub(rb'\$(\$|\{[^}]*\}|[A-Za-z0-9_]+)', ref, replacement)

    def replace(self, data, replacement):
        chunks = []
        pos = 0
        for a, z, m, _ in self.match_objects(data):
            chunks.extend((data[pos:a], self.expand(m, replacement)))
            pos = z
        chunks.append(data[pos:])
        return b''.join(chunks)

    def trim(self, data, how):
        if not how:
            return data
        matches = merge_spans(self.matches(data))
        a, z = 0, len(data)
        if matches and how in ('l', 'b') and matches[0][0] == 0:
            a = matches[0][1]
        if matches and how in ('r', 'b') and matches[-1][1] == len(data):
            z = matches[-1][0]
        return data[a:max(a, z)]


def main():
    write = sys.stdout.buffer.write
    try:
        opt = options(sys.argv[1:])
        if isinstance(opt, str):
            if opt == 'version':
                write(b'tuc 1.3.0\n')
            else:
                text = HELP_TEXT if opt == 'help' else WELCOME_TEXT
                if text is None:
                    text = Path(__file__).with_name(opt + '.txt').read_text()
                write(utf8(text))
            return 0
        try:
