    result = []
    for item in s.split(','):
        if not item:
            raise ParseFailure('Field format error: empty field')
        bare, eq, fallback = item.partition('=')
        fallback = utf8(fallback) if eq else None
        if ':' in bare:
            a, b = bare.split(':', 1)
            if not a and not b:
                raise ParseFailure('Field format error, no numbers next to `:`')
            left = number(a) if a else None
            right = number(b) if b else None
            if left is not None and right is not None and (left > 0) == (right > 0) and left > right:
                raise ParseFailure('Field left value cannot be greater than right value')
            result.append(Bound(left, right, True, fallback))
        else:
            n = number(bare)
            result.append(Bound(n, n, False, fallback))
