def main():
    write = sys.stdout.buffer.write
    try:
        opt = options(sys.argv[1:])
        if isinstance(opt, str):
            if opt == 'version':
                write(b'tuc 1.3.0\n')
            else:
                text = HELP_TEXT if opt == 'help' else WELCOME_TEXT
                if text is None:
                    text = Path(__file__).with_name(opt + '.txt').read_text()
                write(utf8(text))
            return 0
        try:
