            else:
                with open(opt['path'], 'rb') as f:
                    data = f.read()
        except OSError as e:
            runtime(str(e))
        if opt['memory'] is not None:
            cut_stream(data, opt, write)
        elif opt['mode'] == 'bytes':
            cut_bytes(data, opt, write)
        elif opt['mode'] == 'lines' and not opt['compress'] and not opt['complement'] and bounds_forward(opt['parts']):
            cut_lines(data, opt, write)
        else:
            cut_records(data, opt, write)
        sys.stdout.buffer.flush()
        return 0
    except BoundsFailure as e:
        sys.stdout.buffer.flush()
        sys.stderr.buffer.write(utf8('Error: %s\n' % e))
        return 1
    except Failure as e:
        sys.stdout.buffer.flush()
        sys.stderr.buffer.write(utf8(str(e) + '\n'))
        return 1
    except Panic as e:
        # These errors occur before the buffered current record is committed.
        sys.stdout.buffer.flush()
        location = e.location.replace(':19746', ':197:46').replace(':22422', ':224:22')
        sys.stderr.buffer.write(utf8("\nthread 'main' (%d) panicked at %s:\n%s\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n" %
                                     (os.getpid(), location, e.message)))
        sys.stderr.buffer.flush()
        try:
            import resource
            resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
        except (ImportError, ValueError, OSError):
            pass
        os.abort()
    except BrokenPipeError:
        # Do not let Python print a traceback for a closed output pipe.
        try:
            sys.stdout = open(os.devnull, 'w')
        except OSError:
            pass
